@keyframes pulse {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.5;
  }
}

::view-transition-old(page-grid) {
  animation: page-slide-out-left 0.3s ease both;
}

::view-transition-new(page-grid) {
  animation: page-slide-in-left 0.3s ease both;
}

::view-transition-old(page-detail) {
  animation: page-slide-out-right 0.3s ease both;
}

::view-transition-new(page-detail) {
  animation: page-slide-in-right 0.3s ease both;
}

@keyframes page-slide-out-left {
  from {
    transform: translateX(0);
    opacity: 1;
  }
  to {
    transform: translateX(-20%);
    opacity: 0;
  }
}

@keyframes page-slide-in-left {
  from {
    transform: translateX(-20%);
    opacity: 0;
