  animation: page-slide-out-right 0.3s ease both;
}

::view-transition-new(page-detail) {
  animation: page-slide-in-right 0.3s ease both;
}

@keyframes page-slide-out-left {
  from {
    transform: translateX(0);
    opacity: 1;
  }
  to {
    transform: translateX(-20%);
    opacity: 0;
  }
}

@keyframes page-slide-in-left {
  from {
    transform: translateX(-20%);
    opacity: 0;
  }
  to {
    transform: translateX(0);
    opacity: 1;
  }
}

@keyframes page-slide-out-right {
  from {
    transform: translateX(0);
    opacity: 1;
  }
  to {
    transform: translateX(20%);
    opacity: 0;
  }
}

@keyframes page-slide-in-right {
  from {
    transform: translateX(20%);
    opacity: 0;
  }
  to {
    transform: translateX(0);
    opacity: 1;
  }
}

::view-transition-group(product-image-morph) {
  animation-duration: 0.4s;
  animation-timing-function: cubic-bezier(0.2, 0, 0, 1);
}

::view-transition-old(suspense-reveal) {
  animation: suspense-reveal-out 0.25s ease-out both;
}

::view-transition-new(suspense-reveal) {
  animation: suspense-reveal-in 0.25s ease-out both;
}

@keyframes suspense-reveal-out {
  from {
    opacity: 1;
  }
  to {
    opacity: 0;
  }
}

@keyframes suspense-reveal-in {
  from {
    opacity: 0;
    transform: translateY(6px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@media (prefers-reduced-motion: reduce) {
  ::view-transition-group(*),
  ::view-transition-old(*),
  ::view-transition-new(*) {
    animation: none !important;
  }

  .skeleton-image,
  .skeleton-text {
    animation: none;
  }
}

